import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
import { FREQUENCIES } from '../../claudinite-tasks/calendar.mjs';
import { MODEL_FAMILIES } from '../../claudinite-tasks/model-map.mjs';
import { OUTCOMES, LEGACY_OUTCOMES, SIGNAL_NAMES } from '../../claudinite-tasks/task-contract.mjs';
import { validatePreconditions, BUILTIN_TERM_NAMES, termsMap } from '../../claudinite-tasks/precondition-policy.mjs';

// Every scheduler task is a `tasks/<name>/task.mjs` whose default export carries
// the full declaration contract (per-project-scheduling DESIGN §1) with legal
// enum values. This asserts that shape statically at author time — the executor
// and scheduler validate the same contract at run time (task-contract.mjs), so
// an illegal frequency/model/outcome, or a missing field, is caught here first.
//
// RELEVANCE FIRST (engine/checks/README.md): gated on a `tasks/<name>/task.mjs`
// existing, so the check is inert on any repo without tasks. Static text over
// the self-contained module (task.mjs imports nothing), keyed off the canonical
// enum lists so the legal values never drift from the runtime validator.
const TASK_MJS = /(^|\/)tasks\/[^/]+\/task\.mjs$/;

// The `preconditions` value as an array of strings, or null when it is not a
// literal list this check can read. Deliberately strict: a declaration whose
// trigger is computed cannot be audited by anyone reading it, which is the whole
// reason the field is data.
function preconditionsLiteral(code) {
  const m = /\bpreconditions:\s*\[([^\]]*)\]/.exec(code);
  if (!m) return null;
  const body = m[1].trim().replace(/,$/, '');
  if (body === '') return [];
  const entries = body.split(',').map((e) => e.trim()).filter((e) => e !== '');
  const literal = entries.map((e) => /^'([^']*)'$/.exec(e) ?? /^"([^"]*)"$/.exec(e));
  return literal.every(Boolean) ? literal.map((x) => x[1]) : null;
}

// The term names the task's own `preconditions.mjs` exports, read as text: the
// check runs over a file listing, not a module graph, so it recognises a
// task-local condition by the key that defines it. A term the file computes
// rather than spells is not found, and its declaration reads as unknown — which
// is the same "write it so a reader can see it" the literal rule above states.
function siblingTerms(ctx, taskFile) {
  const text = ctx.read(taskFile.replace(/task\.mjs$/, 'preconditions.mjs'));
  if (text === null) return new Map();
  const body = stripComments(text);
  const start = body.indexOf('export const terms');
  if (start === -1) return new Map();
  const names = [...body.slice(start).matchAll(/^  '([^']+)':/gm)].map((m) => m[1]);
  return termsMap(Object.fromEntries(names.map((n) => [n, { signals: [] }])));
}

// A file that only re-exports another module declares nothing of its own — a
// legacy-path shim left behind by a relocation is the shape. The declaration it
// names is scanned where it actually lives, so judging the shim would report the
// same task twice and fail it on text it does not carry.
const isReExport = (text) => {
  const code = text.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('//'));
  return code.length > 0 && code.every((l) => /^(import|export)\b.*\bfrom\b/.test(l) || /^import\s+['"]/.test(l));
};

// The value of a top-level `key: 'value'` string field, or null if absent.
const strField = (text, key) => {
  const m = new RegExp(`\\b${key}:\\s*['"]([^'"]+)['"]`).exec(text);
  return m ? m[1] : null;
};

const rule = {
  id: 'task-declaration-shape',
  severity: 'blocking',
  description: 'A tasks/<name>/task.mjs default-exports the full task contract (id, frequency, preconditions, agent_model, expected_outcome, agent_instructions) with legal enum values and a well-formed precondition expression; a pr task pairs its ceiling with a automerge policy, an agentic task bounds its run with agent_execution_timeout, and any code_work carries a timeout and stays task-local',
  doc: 'packs/claudinite-tasks/README.md',
  why: 'the scheduler run and executor read agent_model/expected_outcome/frequency from this file, not the work item — an illegal or missing value means a task never fires, fires wrong, or writes past its ceiling',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter((f) => TASK_MJS.test(f))) {
      const text = ctx.read(file);
      if (text === null || isReExport(text)) continue;
      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
      const model = strField(text, 'agent_model');

      if (!/export\s+default\s*\{/.test(text)) {
        flag('does not default-export a declaration object', 'export default { id, frequency, preconditions, agent_model, expected_outcome, agent_instructions }');
        continue;
      }
      const enumField = (key, legal) => {
        const v = strField(text, key);
        if (v === null) flag(`declares no "${key}"`, `add "${key}": one of ${legal.join(', ')}`);
        else if (!legal.includes(v)) flag(`"${key}" is "${v}", not a legal value`, `use one of: ${legal.join(', ')}`);
      };
      enumField('frequency', FREQUENCIES);
      enumField('agent_model', MODEL_FAMILIES);

      // expected_outcome takes the ceiling/policy split, with the retired
      // one-word ceilings an ADVISORY rename like the code-work names below:
      // the runtime normalizes them at the door forever, so a member's vendor
      // refresh must not turn its CI red over a declaration nobody edited.
      const outcome = strField(text, 'expected_outcome');
      const hasMayAutomerge = /\bautomerge:\s*/.test(stripComments(text));
      if (outcome === null) {
        flag('declares no "expected_outcome"', `add "expected_outcome": one of ${OUTCOMES.join(', ')}`);
      } else if (LEGACY_OUTCOMES[outcome] !== undefined) {
        out.push(finding(rule, {
          file,
          severity: 'advisory',
          what: `declares the legacy outcome ceiling "${outcome}"`,
          fix: `write the pair it normalizes to: expected_outcome: 'pr', automerge: '${LEGACY_OUTCOMES[outcome]}' — and consider a narrower policy than '${LEGACY_OUTCOMES[outcome]}' (a list of diff classes, e.g. ['comment-only-changes'])`,
        }));
      } else if (!OUTCOMES.includes(outcome)) {
        flag(`"expected_outcome" is "${outcome}", not a legal value`, `use one of: ${OUTCOMES.join(', ')}`);
      } else if (outcome === 'pr' && !hasMayAutomerge) {
        flag('a "pr" task declares no "automerge"', 'say what may land unreviewed: "nothing", "anything", or a list of diff classes, e.g. ["comment-only-changes", "readme-changes"]');
      } else if (outcome === 'none' && hasMayAutomerge) {
        flag('a "none" task declares "automerge"', 'drop it — a task that opens no pull request has nothing to merge; or set expected_outcome: "pr"');
      }

      if (!/\bid:\s*['"]/.test(text)) flag('declares no string "id"', 'add "id": the task name (matching its directory)');
      // agent_instructions is required only for an agentic task (agent_model !==
      // 'none') — that's the worker file the agent reads. A `none` task runs no
      // agent, so the field is not applicable.
      if (model !== 'none' && !/\bagent_instructions:\s*['"]/.test(text)) {
        flag('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'add "agent_instructions": the worker file beside task.mjs (e.g. "task.md")');
      }
      // The precondition, in exactly one of its two forms. The declarative
      // `preconditions` expression is what the canon writes and what this check
      // can actually READ — an expression is text, where a function body is
      // opaque — so unknown terms and malformed arguments are author-time
      // findings here. The legacy function stays accepted forever for a member's
      // own local task files, which nothing converges; it is only never both.
      const code = stripComments(text);
      // `preconditions` is the only gate a task declares (#1617). Both retired
      // spellings are flagged by NAME rather than merely going unrecognised, so a
      // declaration carrying one is told what replaced it instead of reading as a
      // task that simply forgot its gate.
      if (/\bprecondition\s*[:(]/.test(code.replace(/\bpreconditions\b/g, '').replace(/\bprecondition_signals\b/g, ''))) {
        flag('declares a "precondition" function, which is retired', 'move the gate into "preconditions" — a built-in condition, or a term this task\'s preconditions.mjs exports');
      }
      if (/\bprecondition_signals:\s*\[/.test(code)) {
        flag('declares "precondition_signals", which is retired', 'drop it — the signal union is derived from the conditions, each of which names what it reads');
      }
      if (!/\bpreconditions:\s*\[/.test(code)) {
        flag('declares no "preconditions"',
          `add "preconditions": a list of conditions that must all hold — built-ins are ${BUILTIN_TERM_NAMES.join(', ')}, plus 'none' for a task the calendar or a filed item triggers`);
      } else {
        const expression = preconditionsLiteral(code);
        if (expression === null) {
          flag('"preconditions" is not a literal list of condition strings', `write it as a literal, e.g. preconditions: ['substantive-change'] — a computed expression is unreadable to this check and to the next person`);
        } else {
          for (const problem of validatePreconditions(expression, siblingTerms(ctx, file))) flag(problem.what, problem.fix);
        }
      }

      // The code-work/timeout guards (task-code-work DESIGN §2). Numeric presence is
      // a cheap `<key>: <digit>` regex, matching the runtime contract. TWO
      // generations of legacy field names still satisfy the contract — the loader
      // normalizes both — but each earns its own rename finding so the fleet
      // converges on the canonical names.
      const hasNum = (...keys) => keys.some((key) => new RegExp(`\\b${key}:\\s*\\d`).test(text));
      const LEGACY_CODE_WORK = [
        { field: 'agent_preprocessing', timeout: 'agent_preprocessing_timeout' },
        { field: 'prework', timeout: 'prework_timeout' },
      ];
      const legacyDeclared = LEGACY_CODE_WORK.filter(({ field }) => new RegExp(`\\b${field}:\\s*['"]`).test(text));
      const hasCodeWork = /\bcode_work:\s*['"]/.test(text) || legacyDeclared.length > 0;
      for (const { field, timeout } of legacyDeclared) {
        // ADVISORY, deliberately, on a blocking rule: the legacy names still
        // satisfy the runtime contract (normalized at load), and a member's
        // vendor refresh must not turn its CI red over files nothing has renamed
        // yet. This finding IS the durable driver of the rename — it names the
        // exact edit and does not age out, which is why neither rename ships a
        // migration note.
        out.push(finding(rule, {
          file,
          severity: 'advisory',
          what: `declares code_work under the legacy name "${field}"`,
          fix: `rename "${field}" → "code_work" and "${timeout}" → "code_work_timeout" (the two phases of task execution are code-work, then agentic-work — neither is named for the other)`,
        }));
      }
      // The ordering field's rename. ADVISORY for the same reason as the code-work rename above:
      // the runtime normalizes it at the door, so a member's own task file keeps working and its
      // CI must not go red over a declaration nobody has edited. Worth making because the bare
      // preposition invited reading the field as a time — it is not one; it names task ids, and
      // what it steers is when the item is scheduled onto an executor.
      //
      // The regex is anchored on a NON-word character before the key so it cannot match the
      // canonical spelling's own tail.
      if (/(?<![\w.])after:\s*\[/.test(text)) {
        out.push(finding(rule, {
          file,
          severity: 'advisory',
          what: 'declares its ordering under the legacy name "after"',
          fix: 'rename "after" to "schedule_after" (it names task ids, not a time — what it steers is when this item is scheduled onto an executor)',
        }));
      }
      // `session_scope` lost its last reader with the slot scheduler (#974): the
      // queue routes a hand-off by `invocation_endpoint`, and nothing anywhere
      // asks a task what its scope is. ADVISORY, like the code-work rename above and
      // for the same reason — the field still VALIDATES, so a member's vendor
      // refresh must not turn its CI red over a declaration nobody has edited yet;
      // this only keeps the dead field visible until it is dropped.
      // Comments stripped: this rule's own remedy names the field, and so does any
      // note explaining why a task stopped declaring one.
      if (/\bsession_scope:\s*['"]/.test(stripComments(text))) {
        out.push(finding(rule, {
          file,
          severity: 'advisory',
          what: 'declares "session_scope", which nothing reads',
          fix: 'drop it — reach is a property of which endpoint the hand-off calls, so a task needing wider access declares "invocation_endpoint": <a key in the repo\'s taskScheduler.agenticTaskInvocationEndpoints> instead',
        }));
      }
      if (model && MODEL_FAMILIES.includes(model) && model !== 'none' && !hasNum('agent_execution_timeout')) {
        flag('an agentic task (agent_model !== "none") declares no numeric "agent_execution_timeout"', 'add "agent_execution_timeout": seconds bounding the agentic run');
      }
      if (model === 'none' && !hasCodeWork) {
        flag('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
      }
      if (hasCodeWork) {
        const prep = LEGACY_CODE_WORK.reduce((found, { field }) => found ?? strField(text, field), strField(text, 'code_work'));
        if (prep && (/(^|\s)\//.test(prep) || prep.includes('..'))) {
          flag('"code_work" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
        }
        if (!hasNum('code_work_timeout', ...LEGACY_CODE_WORK.map(({ timeout }) => timeout))) {
          flag('"code_work" is set but declares no numeric "code_work_timeout"', 'add "code_work_timeout": seconds after which the subprocess is killed');
        }
      }
    }
    return out;
  },
};

export default rule;
##### matches-folder
import { finding } from '../../../engine/checks/helpers/findings.mjs';

// The other half of the task contract (the writing-tasks skill, "Every task
// declaration carries the full contract" + "The task folder"): the declaration
// and the folder it sits in must AGREE. `task-declaration-shape` asserts the
// declaration's own shape — that `id` and `agent_instructions` are present and
// the enums are legal — and stops at the file's edge; this rule is the
// cross-artifact invariant between that file and the tree around it.
//
// Why it is its own rule rather than more of that one: both faces fail the same
// way, and it is the way a shape error does NOT fail. Discovery
// (packs/claudinite-tasks/discover.mjs) is fail-soft per task — a task whose declared
// `id` differs from its directory name is dropped into `errors` and simply never
// runs, and a dangling `agent_instructions` hands the executor a worker doc that
// isn't there. Nothing goes red; the scheduler keeps reporting healthy runs while
// the task is silently absent from every one of them. That is the class this
// repo's own canon names as the expensive one, so it is worth catching where it
// is cheap: at author time, in the session that wrote the file.
//
// RELEVANCE FIRST (engine/checks/README.md): gated on a `tasks/<name>/task.mjs`
// existing, so the rule is inert on any repo that schedules nothing. Static text
// over the self-contained module (task.mjs imports nothing), the same parse the
// shape rule uses, so the two views of one file can't disagree.
const TASK_MJS = /(^|\/)tasks\/([^/]+)\/task\.mjs$/;

// The value of a top-level `key: 'value'` string field, or null if absent.
const strField = (text, key) => {
  const m = new RegExp(`\\b${key}:\\s*['"]([^'"]+)['"]`).exec(text);
  return m ? m[1] : null;
};

const rule = {
  id: 'task-declaration-matches-folder',
  severity: 'blocking',
  description: "A tasks/<name>/task.mjs declares the id of its own directory, and its agent_instructions names a worker file that exists beside it",
  doc: 'packs/claudinite-growth/skills/writing-tasks/SKILL.md',
  why: 'task discovery is fail-soft per task — a declaration that disagrees with its folder is dropped into errors and the task silently never runs, while every scheduler run keeps reporting healthy',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      const m = TASK_MJS.exec(file);
      if (!m) continue;
      const dirName = m[2];
      const text = ctx.read(file);
      if (text === null) continue;
      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));

      const id = strField(text, 'id');
      if (id !== null && id !== dirName) {
        flag(
          `declares id "${id}" but its directory is "${dirName}"`,
          `rename the directory to "${id}", or set the id to "${dirName}" — the two must match`,
        );
      }

      // The worker doc the executing agent reads. Resolved relative to the task
      // folder, which is the only place it may live (the declaration contract
      // keeps a task self-contained), so a value that escapes the folder is
      // dangling by definition and reported as such.
      const worker = strField(text, 'agent_instructions');
      if (worker) {
        const taskDir = file.slice(0, file.length - 'task.mjs'.length);
        if (worker.startsWith('/') || worker.split('/').includes('..')) {
          flag(
            `declares agent_instructions "${worker}", which reaches outside the task directory`,
            `keep the worker doc beside task.mjs (conventionally "task.md") — a task folder is self-contained`,
          );
        } else if (!ctx.exists(`${taskDir}${worker}`)) {
          flag(
            `declares agent_instructions "${worker}", which does not exist in ${taskDir}`,
            `add ${taskDir}${worker}, or point agent_instructions at the worker doc that is there (conventionally "task.md")`,
          );
        }
      }
    }
    return out;
  },
};

export default rule;
##### routine-structure
import { dirname, join, basename } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';

// A routine (or a per-project-scheduling task, §1) is a folder whose entry point is
// `routine.md` OR `task.md`, alongside the deterministic scripts it invokes. This
// check asserts the prose↔script wiring that the unattended-agents skill mandates,
// for both shapes: a legacy `dev/routines/<name>/routine.md` and a converted
// `.../tasks/<name>/task.md` earn the same guard (a task folder's `task.mjs`
// carries the declaration; its `task.md` is the worker prose the scripts hang off).
//
// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): a skill check has no
// declaration gate — the engine runs it on EVERY repo, including ones with no
// routines — so `run` must detect relevance before asserting anything. Here the
// signal is a `routine.md`/`task.md` existing: `routineDirs` is empty on any repo
// without one, every loop below is over an empty set, and the check no-ops. Keep
// that gate narrow and up front; a broad signal would fire false findings everywhere.
const ENTRY_NAMES = ['routine.md', 'task.md'];
const isEntry = (f) => ENTRY_NAMES.includes(basename(f));
const PHASE_SCRIPTS = ['preconditions.sh', 'postconditions.sh'];

// Direct-child files of dir `d` within `files` matching `pred` (not descendants).
function children(files, d, pred) {
  const prefix = d ? d + '/' : '';
  return files.filter((f) => {
    if (!f.startsWith(prefix)) return false;
    const rel = f.slice(prefix.length);
    return rel.length > 0 && !rel.includes('/') && pred(rel);
  });
}

const rule = {
  id: 'routine-structure',
  severity: 'blocking',
  description: 'A routine/task folder has a routine.md or task.md entry point wired to the scripts it invokes',
  doc: 'skills/unattended-agents/SKILL.md',
  why: 'a routine is prose (read) + scripts (executed); a dangling invocation or an orphan/entry-less script means the agent runs the wrong thing or the job hides where it is never read',

  run(ctx) {
    const out = [];
    const files = ctx.files;

    // dir -> its entry file name (routine.md or task.md). A folder carries one or
    // the other; if it somehow had both, the first wins (they wire the same scripts).
    const entryOf = new Map();
    for (const f of files.filter(isEntry)) {
      const d = dirname(f);
      if (!entryOf.has(d)) entryOf.set(d, basename(f));
    }
    const routineDirs = new Set(entryOf.keys());

    for (const [dir, ENTRY] of entryOf) {
      const text = ctx.read(join(dir, ENTRY));
      if (text === null) continue;
      const lines = text.split('\n');
      const scripts = children(files, dir, (rel) => rel.endsWith('.sh'));

      // 1. Every `bash …/x.sh` the prose tells you to run must resolve.
      lines.forEach((ln, i) => {
        const m = /\b(?:bash|sh)\s+(\S+\.sh)\b/.exec(ln);
        if (!m) return;
        const p = m[1];
        if (ctx.exists(p) || ctx.exists(join(dir, p))) return;
        out.push(finding(rule, {
          file: join(dir, ENTRY), line: i + 1,
          what: `invokes ${p}, which does not exist`,
          fix: 'correct the path or restore the script; a routine must not tell the agent to run a missing file',
        }));
      });

      // 2. Every script in the folder must be invoked by the entry point — an
      //    uninvoked script is dead weight or an indirection that never ran.
      for (const s of scripts) {
        if (text.includes(basename(s))) continue;
        out.push(finding(rule, {
          file: s, line: null, severity: 'advisory',
          what: `is never invoked by ${join(dir, ENTRY)}`,
          fix: `invoke it from ${ENTRY}, or remove it — a script the routine never runs does not earn its place`,
        }));
      }

      // 3. Each script must be a real executable script (shebang first line).
      for (const s of scripts) {
        const body = ctx.read(s);
        if (body === null || body.startsWith('#!')) continue;
        out.push(finding(rule, {
          file: s, line: 1, severity: 'advisory',
          what: 'has no shebang line',
          fix: 'start the script with a shebang (e.g. #!/usr/bin/env bash) so it runs standalone',
        }));
      }
    }

    // 4. A folder carrying phase scripts but no routine.md/task.md has lost its
    //    entry point — the standard name is how the routine or task is found and run.
    const phaseDirs = new Set(
      files.filter((f) => PHASE_SCRIPTS.includes(basename(f))).map((f) => dirname(f)),
    );
    for (const dir of phaseDirs) {
      if (routineDirs.has(dir)) continue;
      out.push(finding(rule, {
        file: join(dir, PHASE_SCRIPTS.find((n) => ctx.exists(join(dir, n))) || PHASE_SCRIPTS[0]),
        line: null,
        what: `sits in a routine folder with no ${ENTRY_NAMES.join(' / ')} entry point`,
        fix: `add ${ENTRY_NAMES.join(' or ')} as the folder's entry point (it invokes these scripts), or move the scripts out`,
      }));
    }

    return out;
  },
};

export default rule;
