// Where a task's declaration lives and how it is read — the one place that knows
// a task folder may spell its declaration two ways. `task.json` is the
// declaration: plain data, pointing at `task.schema.json` through `$schema`, and
// readable by anything that can parse JSON, the dashboard's API reads included.
// `task.mjs` (a default-exported object literal) is the retired module form,
// still accepted at the door so a member's own local-pack tasks keep running
// until its nightly update converts them (the `task-declarations-json` record).
//
// Everything that resolves a declaration — discovery, the dispatch validators,
// the checks that gate on a task folder — goes through the names here, so the
// retirement of the module form is one edit in one file.

import { existsSync, readFileSync } from 'node:fs';
import { basename, dirname, join } from 'node:path';
import { pathToFileURL } from 'node:url';

// Canonical first: when a folder carries both, the JSON is the declaration and
// the module is a leftover the converter did not get to delete.
export const TASK_DECLARATION_FILE = 'task.json';
export const LEGACY_TASK_DECLARATION_FILE = 'task.mjs';
export const TASK_DECLARATION_FILES = [TASK_DECLARATION_FILE, LEGACY_TASK_DECLARATION_FILE];

// The file-listing form of the same fact, for the checks and the dashboard, which
// select a task folder out of a path list rather than probing a directory. Group 1
// is the task's directory name, group 2 the declaration file's extension.
export const TASK_DECLARATION_PATH_RE = /(^|\/)tasks\/([^/]+)\/task\.(json|mjs)$/;
export const isTaskDeclarationPath = (path) => TASK_DECLARATION_PATH_RE.test(path);
export const isLegacyTaskDeclarationPath = (path) => path.endsWith(`/${LEGACY_TASK_DECLARATION_FILE}`) && isTaskDeclarationPath(path);

// The declaration file a task directory carries, or null when it carries none.
// Both present is not "prefer one": it is two declarations for one task, and the
// caller reports it rather than guessing which the author meant.
export function findTaskDeclaration(taskDir) {
  const present = TASK_DECLARATION_FILES.filter((name) => existsSync(join(taskDir, name)));
  if (present.length === 0) return null;
  if (present.length > 1) {
    throw new Error(`${taskDir} carries both ${present.join(' and ')} — delete ${LEGACY_TASK_DECLARATION_FILE}, ${TASK_DECLARATION_FILE} is the declaration`);
  }
  return join(taskDir, present[0]);
}

// The declaration's raw object, before normalization. A JSON file that does not
// parse, or a module that does not import, throws with the file's own message —
// the callers turn that into a per-task error, never a sunk scan.
export async function loadTaskDeclaration(file) {
  if (basename(file) === TASK_DECLARATION_FILE) return parseTaskDeclaration(readFileSync(file, 'utf8'));
  return (await import(pathToFileURL(file).href)).default;
}

// A `task.json`'s text as the declaration object. `$schema` is the editor's
// pointer, not a field of the contract, and leaves here.
export function parseTaskDeclaration(text) {
  const decl = JSON.parse(text);
  if (decl !== null && typeof decl === 'object' && !Array.isArray(decl)) delete decl.$schema;
  return decl;
}

// The declaration file a `.../tasks/<name>/task.md` path's folder carries, given
// only an `exists` capability over repo-relative paths (the dispatch validator's
// world). Same rule as `findTaskDeclaration`; a folder with both returns null with
// `both: true` so the caller can say so.
export function siblingTaskDeclaration(taskMdPath, exists) {
  const dir = dirname(taskMdPath);
  const present = TASK_DECLARATION_FILES.map((name) => `${dir}/${name}`).filter((p) => exists(p));
  if (present.length === 1) return { file: present[0], both: false };
  return { file: null, both: present.length > 1 };
}
