import { readFileSync, writeFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
import { nextVersion } from './engine/version.mjs';
const files = execSync('git diff --name-only --diff-filter=U').toString().trim().split('\n');
for (const f of files) {
  const src = readFileSync(f, 'utf8');
  const m = /<<<<<<< HEAD\n  version: '([\d.]+)',\n=======\n  version: '([\d.]+)',\n>>>>>>> [^\n]*\n/.exec(src);
  if (!m) throw new Error(`unexpected conflict shape in ${f}`);
  const next = nextVersion(m[1]);
  writeFileSync(f, src.replace(m[0], `  version: '${next}',\n`));
  const log = f.replace('pack.mjs', 'VERSIONS.md');
  const rows = readFileSync(log, 'utf8');
  if (!rows.includes(`| ${m[2]} | 2026-09-02 |`)) throw new Error(`${log}: no row for ${m[2]}`);
  writeFileSync(log, rows.replace(`| ${m[2]} | 2026-09-02 |`, `| ${next} | 2026-09-02 |`));
  console.log(f, `main ${m[1]}, mine ${m[2]} -> ${next}`);
}
EOF
